BEGIN;

CREATE TABLE schema_migrations (
    version    bigint PRIMARY KEY,
    applied_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE app_settings (
    key   text PRIMARY KEY,
    value text NOT NULL

);

CREATE TABLE availability_audit (
    id           bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    decision_id  bigint,
    at           double precision NOT NULL,
    actor        text NOT NULL DEFAULT '',
    from_status  text,
    to_status    text,
    event        text NOT NULL,
    detail       text NOT NULL DEFAULT ''

);

CREATE TABLE classifications (
    event_key         text PRIMARY KEY,
    kind              text NOT NULL,
    confidence        text NOT NULL,
    source            text NOT NULL,
    needs_review      bigint NOT NULL DEFAULT 1,
    rationale         text NOT NULL DEFAULT '',
    note              text NOT NULL DEFAULT '',
    export_approved   bigint NOT NULL DEFAULT 0,
    export_suppressed bigint NOT NULL DEFAULT 0,
    decided_at        double precision NOT NULL

);

CREATE TABLE conflict_acknowledgements (
    conflict_id     text PRIMARY KEY,
    acknowledged_at double precision NOT NULL,
    note            text NOT NULL DEFAULT ''

);

CREATE TABLE feed_publications (
    id            bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    destination   text NOT NULL,
    property_id   bigint NOT NULL,
    revision      bigint NOT NULL,
    generated_at  double precision NOT NULL,
    entry_count   bigint NOT NULL DEFAULT 0,
    checksum      text NOT NULL DEFAULT '',
    status        text NOT NULL DEFAULT 'generated',
    published_at  double precision,
    detail        text NOT NULL DEFAULT ''
, stage text NOT NULL DEFAULT 'generated', uploaded_at double precision, cache_invalidated_at double precision, verified_at double precision, removal_approved_by text, removal_approved_at double precision, diff_summary text NOT NULL DEFAULT '', safety_verdict text NOT NULL DEFAULT '', failure_detail text
);

CREATE TABLE feed_snapshots (
    id                  bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    property_id         bigint NOT NULL,
    destination         text NOT NULL,
    revision            bigint NOT NULL,
    generated_at        double precision NOT NULL,
    published_at        double precision,
    checksum            text NOT NULL,
    entry_count         bigint NOT NULL DEFAULT 0,
    covered_nights      bigint NOT NULL DEFAULT 0,
    payload             text NOT NULL DEFAULT '',
    entry_uids          text NOT NULL DEFAULT '',
    is_last_known_good  bigint NOT NULL DEFAULT 0

);

CREATE TABLE feed_tokens (
    id            bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    property_id   bigint NOT NULL,
    destination   text NOT NULL,
    version       bigint NOT NULL,
    credential_ref text NOT NULL,
    created_at    double precision NOT NULL,
    retired_at    double precision,
    UNIQUE(property_id, destination, version)

);

CREATE TABLE listing_connection_events (
    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    listing_id  bigint NOT NULL,
    at          double precision NOT NULL,
    from_state  text,
    to_state    text NOT NULL,
    actor       text NOT NULL DEFAULT '',
    detail      text NOT NULL DEFAULT '',
    http_status bigint

);

CREATE TABLE properties (
    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name        text NOT NULL,
    address     text NOT NULL DEFAULT '',
    notes       text NOT NULL DEFAULT '',
    created_at  double precision NOT NULL,
    updated_at  double precision NOT NULL
, time_zone text NOT NULL DEFAULT 'UTC', archived_at double precision
);

CREATE TABLE sync_runs (
    id                     bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    listing_id             bigint NOT NULL,
    started_at             double precision NOT NULL,
    finished_at            double precision,
    outcome                text NOT NULL,
    http_status            bigint,
    events_seen            bigint NOT NULL DEFAULT 0,
    events_inserted        bigint NOT NULL DEFAULT 0,
    events_updated         bigint NOT NULL DEFAULT 0,
    events_tombstoned      bigint NOT NULL DEFAULT 0,
    events_needing_review  bigint NOT NULL DEFAULT 0,
    error_message          text

);

CREATE TABLE availability_decisions (
    id                    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    property_id           bigint NOT NULL
                          REFERENCES properties(id) ON DELETE CASCADE,
    destination           text NOT NULL,
    action                text NOT NULL,
    start_day             double precision NOT NULL,
    end_day               double precision NOT NULL,
    status                text NOT NULL,
    reason                text NOT NULL DEFAULT '',
    publication_uid       text NOT NULL,
    created_at            double precision NOT NULL,
    updated_at            double precision NOT NULL,
    validated_at          double precision,
    approved_at           double precision,
    approved_by           text,
    published_at          double precision,
    refresh_expected_by   double precision,
    verified_at           double precision,
    cancelled_at          double precision,
    failure_reason        text,
    supersedes_id         bigint,
    created_by            text NOT NULL DEFAULT ''

);

CREATE TABLE platform_listings (
    id                   bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    property_id          bigint NOT NULL
                         REFERENCES properties(id) ON DELETE CASCADE,
    platform             text NOT NULL,
    label                text NOT NULL DEFAULT '',
    ical_url             text NOT NULL DEFAULT '',
    auto_refresh_enabled bigint NOT NULL DEFAULT 1,
    last_sync_at         double precision,
    last_sync_summary    text NOT NULL DEFAULT '',
    created_at           double precision NOT NULL,
    updated_at           double precision NOT NULL
, url_storage text NOT NULL DEFAULT 'database', credential_ref text NOT NULL DEFAULT '', connection_state text NOT NULL DEFAULT 'unknown', connection_changed_at double precision, connection_detail text NOT NULL DEFAULT ''
);

CREATE TABLE published_feed_entries (
    id              bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    publication_id  bigint NOT NULL
                    REFERENCES feed_publications(id) ON DELETE CASCADE,
    entry_uid       text NOT NULL,
    origin          text NOT NULL,
    source_event_key text,
    decision_id     bigint,
    start_day       double precision NOT NULL,
    end_day         double precision NOT NULL,
    summary         text NOT NULL

);

CREATE TABLE events (
    id                         bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    listing_id                 bigint NOT NULL
                               REFERENCES platform_listings(id) ON DELETE CASCADE,
    event_key                  text NOT NULL UNIQUE,
    uid                        text NOT NULL,
    recurrence_id              text,
    platform                   text NOT NULL,
    summary                    text NOT NULL DEFAULT '',
    details                    text NOT NULL DEFAULT '',
    location                   text NOT NULL DEFAULT '',
    check_in                   double precision NOT NULL,
    check_out                  double precision NOT NULL,
    is_all_day                 bigint NOT NULL DEFAULT 1,
    feed_status                text NOT NULL DEFAULT 'confirmed',
    sequence                   bigint NOT NULL DEFAULT 0,
    last_modified              double precision,
    content_hash               text NOT NULL DEFAULT '',
    first_seen_at              double precision NOT NULL,
    last_seen_at               double precision NOT NULL,
    is_tombstoned              bigint NOT NULL DEFAULT 0,
    has_unsupported_recurrence bigint NOT NULL DEFAULT 0

);

INSERT INTO schema_migrations (version) VALUES (10);

COMMIT;
